import {createCompass} from './compass.js';
import {argumentDiagram,thoughtDiagram} from './visuals.js';
import {createConceptPictures} from './concept-illustrations.js';
const e=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const $=id=>document.getElementById(id);
const button=(label,action,cls='secondary-button')=>`<button type="button" class="${cls}" data-studio-action="${action}">${label}</button>`;
const when=t=>new Date(t).toLocaleString('zh-CN');
export function conversationRecords(session){
 return (session?.messages||[]).filter((m,i,all)=>m.role==='user'&&!m.error&&!all[i+1]?.error&&!all[i+1]?.pending&&typeof m.content==='string'&&m.content.trim()&&!/^(进入下一环节|暂时跳过|继续之前)/.test(m.content)).map(m=>m.content).slice(-20);
}
export function latestConversationAssessment(assessments,sessionId,kind='profile'){
 if(!sessionId)return null;
 return assessments.filter(a=>a.session===sessionId&&a.kind===kind&&!a.baseline).sort((a,b)=>(a.time||0)-(b.time||0)).at(-1)||null;
}
export function storeConversationAssessment(assessments,record){
 const previous=record.kind==='profile'&&!record.baseline?latestConversationAssessment(assessments,record.session):null;
 if(previous){const id=previous.id;Object.assign(previous,record,{id});return previous;}
 assessments.push(record);return record;
}
export function createStudio(ctx){
 const conceptPictures=createConceptPictures(ctx);
 let catalog=null,account=null,tab='profile',scope='guest',data={},quiz=null,quizResult=null,battle=null,tick=null,clockOffset=0,loadBusy=false,background=0,voice=null,voiceEnabled=false,voiceSending=false,reflectionSessionId=null;
 let workspaceKey='',panelSession=null,panelAgent='coach',chatScroll=0,loadedKey='',renderSequence=0;
 const workspace=document.createElement('dialog');workspace.id='workspace-dialog';workspace.setAttribute('aria-labelledby','workspace-dialog-title');
 workspace.innerHTML='<div class="workspace-dialog-heading"><div><small>当前伙伴 · 专项工具</small><h2 id="workspace-dialog-title">专项工具</h2></div><button type="button" class="secondary-button" data-close-workspace aria-label="关闭专项工具">关闭，返回对话 ×</button></div>';
 const host=document.createElement('section');host.id='studio-view';host.className='studio-view workspace-body';host.hidden=true;workspace.append(host);document.body.append(workspace);
 const closeWorkspace=()=>{if(workspace.open)workspace.close();};
 workspace.addEventListener('close',()=>{host.hidden=true;requestAnimationFrame(()=>{$('message-scroll').scrollTop=chatScroll;});});
 const dialog=document.createElement('dialog');dialog.id='studio-dialog';dialog.className='wide-dialog';document.body.append(dialog);
 const auth=document.createElement('dialog');auth.id='auth-dialog';auth.innerHTML=`<div class="dialog-heading"><h2>进入你的思辨空间</h2><button type="button" data-auth-close class="icon-button" aria-label="关闭">×</button></div><p>账号保存积分、段位和徽章。对话与答题明细保留在当前浏览器。登录后使用独立的本机学习空间，访客记录保留，退出登录后可继续查看。</p><form id="auth-form"><label>账号<input id="auth-name" autocomplete="username" minlength="2" maxlength="20" required></label><label>密码<input id="auth-password" type="password" autocomplete="current-password" minlength="8" maxlength="128" required></label><p id="auth-result" role="status"></p><div class="dialog-actions"><button class="secondary-button" type="submit" name="action" value="register">注册</button><button class="primary-button" type="submit" name="action" value="login">登录</button></div></form>`;document.body.append(auth);
 const getDefault=()=>({chapterReports:[],chapterMastered:[],assessments:[],quizReports:[],mastered:[],battles:[],tables:[],essays:[],reflections:[]});
 function read(){try{data={...getDefault(),...JSON.parse(localStorage.getItem('six-arts-studio:'+scope)||'{}')};}catch{data=getDefault();}for(const k of Object.keys(getDefault()))if(!Array.isArray(data[k]))data[k]=[];}
 function save(){try{localStorage.setItem('six-arts-studio:'+scope,JSON.stringify(data));}catch{ctx.toast('本地空间不足，请先导出学习记录。');}}
 read();
 const compass=createCompass({api:ctx.api,data:()=>data,host:()=>host,save,toast:ctx.toast,account:u=>{account=u;},render:()=>render('compass')});
 function addAssessment(record){
  if(record.kind==='profile'&&!record.baseline){record.session=record.session||ctx.session()?.id||'local-profile';if(!data.assessments.some(a=>a.kind==='profile'&&a.baseline&&a.session===record.session))data.assessments.push({...record,id:crypto.randomUUID(),baseline:true});}
  return storeConversationAssessment(data.assessments,record);
 }
 function showDialog(title,html){dialog.innerHTML=`<div class="dialog-heading"><h2>${e(title)}</h2><button class="icon-button" data-studio-close aria-label="关闭">×</button></div>${html}`;if(!dialog.open)dialog.showModal();}
 const pageLinks=pages=>pages.map(p=>`<a href="/api/textbook.pdf#page=${p+7}" target="_blank" rel="noopener">P${p}</a>`).join(' ');
 function radar(ratings,compare=null){
  const n=ratings.length,cx=175,cy=160,r=105,point=(i,v)=>[cx+Math.cos(-Math.PI/2+i*2*Math.PI/n)*r*v/4,cy+Math.sin(-Math.PI/2+i*2*Math.PI/n)*r*v/4];
  const pts=items=>items.map((d,i)=>point(i,d.score??0).join(',')).join(' ');
  return `<div class="radar-wrap"><svg viewBox="0 0 350 325" role="img" aria-label="练习表现雷达图">${[1,2,3,4].map(v=>`<polygon class="radar-grid" points="${Array.from({length:n},(_,i)=>point(i,v).join(',')).join(' ')}"/>`).join('')}${ratings.map((d,i)=>`<line class="radar-axis" x1="${cx}" y1="${cy}" x2="${point(i,4)[0]}" y2="${point(i,4)[1]}"/>`).join('')}${compare?.every(d=>d.score!==null)?`<polygon class="radar-previous" points="${pts(compare)}"/>`:''}${ratings.every(d=>d.score!==null)?`<polygon class="radar-current" points="${pts(ratings)}"/>`:''}${(compare||[]).map((d,i)=>d.score===null?'':`<circle cx="${point(i,d.score)[0]}" cy="${point(i,d.score)[1]}" r="4" fill="none" stroke="#c99b50" stroke-width="2"/>`).join('')}${ratings.map((d,i)=>{const p=point(i,4.85),v=point(i,d.score??0);return `${d.score!==null?`<circle cx="${v[0]}" cy="${v[1]}" r="4" fill="#2d7264"/>`:''}<text data-axis-index="${i}" tabindex="0" role="button" x="${p[0]}" y="${p[1]}" text-anchor="middle" dominant-baseline="middle">${e(d.label)}</text>`;}).join('')}</svg><div class="radar-legend"><span>● 本次表现</span>${compare?'<span>┄ 对比数据</span>':''}<small>0–4级 · 空缺表示待观察</small></div></div>`;
 }
 function assessmentCard(record,index){const previous=null;return `<section class="lab-card assessment-card" data-assessment="${index}"><div class="card-top"><h3>${record.kind==='socratic'?'本次六维思考表现':'五维学习画像'}</h3><span>${when(record.time)}</span></div><label class="compare-picker">对比<select data-assessment-compare="${index}"><option value="current">仅当前对话</option><option value="baseline">本次前后</option></select></label><div class="radar-slot">${radar(record.ratings,previous?.ratings)}</div><p class="muted compare-note">仅显示当前对话的最新表现；可主动选择本次前后对照。</p><div class="rating-evidence">${record.ratings.map((d,i)=>`<button data-rating="${index}:${i}"><span>${e(d.label)}</span><b>${d.score===null?'待观察':d.score+' / 4'}</b><small>查看原话依据 ↗</small></button>`).join('')}</div><details><summary>评分标准与范围</summary><p>这是平台形成性评价，不是标准化能力量表；分数变化不单独证明能力提升。</p>${catalog.ratingScale.map(s=>`<p>${e(s)}</p>`).join('')}${record.ratings.map(d=>`<p><b>${e(d.label)}</b>：${e(d.criterion)}</p>`).join('')}</details></section>`;}
 function recommendation(){
  const last=data.assessments.filter(a=>a.kind==='profile'&&!a.baseline).at(-1),weak=last?.ratings.filter(d=>d.score!==null&&d.score<3).sort((a,b)=>a.score-b.score)[0],miss=data.quizReports.filter(q=>q.results?.some(r=>!r.correct)).at(-1);
  const target=weak?catalog.nodes.find(n=>n.dimension===weak.id||(weak.id==='reflection'&&n.id==='evaluation')):catalog.nodes.find(n=>n.id===miss?.node);if(!target)return '';
  const index=catalog.nodes.indexOf(target),required=catalog.nodes.slice(0,index).find(n=>!data.mastered.includes(n.id)),next=required||target;
  return `<section class="lab-card personal-task"><span class="seal">下一步微目标</span><h3>${e(target.title)}</h3><p>${weak?'根据最近对话，“'+e(weak.label)+'”还有巩固空间。':'根据最近一次作答，本节点还有未答对的题目。'}</p>${weak?.quote?'<blockquote>'+e(weak.quote)+'</blockquote><p>'+e(weak.reason)+'</p>':''}<p><b>本次产出：</b>${e(target.goal)} 完成五题练习，逐题说明选择依据，再依据解析修正。</p><div class="book-links">教材回溯：${pageLinks(target.pages)}</div>${required?'<p>当前先完成前置节点“'+e(required.title)+'”，达标后沿路径到达本目标。</p>':''}<button type="button" class="primary-button" data-quiz-node="${next.id}" data-quiz-phase="practice">开始${e(next.title)}的针对练习</button></section>`;
 }
 function learning(){if(quiz)return quizHTML();const latest=data.assessments.filter(a=>a.kind==='profile').at(-1);const weakest=latest?.ratings.filter(d=>d.score!==null).sort((a,b)=>a.score-b.score)[0];return `<div class="learning-intro lab-card"><h2>先读教材，再检验理解。</h2><p>练习优先采用教材原题整理，保留题号与原页；不足部分依据教材生成。每节点五题，答对至少四题才解锁下一节点。</p><p class="muted">当前 ${catalog.questionCount} 题，其中 ${catalog.extracted} 题为教材习题整理。${weakest?'依据最近表现，可优先巩固“'+e(weakest.label)+'”。':''}</p></div>${recommendation()}<div class="learning-path">${catalog.nodes.map((n,i)=>{const unlocked=i===0||data.mastered.includes(catalog.nodes[i-1].id),passed=data.mastered.includes(n.id),pre=data.quizReports.filter(r=>r.node===n.id&&r.phase==='pre').at(-1),post=data.quizReports.filter(r=>r.node===n.id&&r.phase==='post').at(-1);return `<section class="path-node ${!unlocked?'locked':''}"><div class="path-number">${passed?'✓':String(i+1).padStart(2,'0')}</div><div class="lab-card"><div class="card-top"><h3>${e(n.title)}</h3><span>${passed?'已通过':unlocked?'可开始':'待解锁'}</span></div><p>${e(n.goal)}</p><div class="book-links">① 学 · ${pageLinks(n.pages)}</div><div class="node-actions"><button class="primary-button" data-quiz-node="${n.id}" data-quiz-phase="practice" ${unlocked?'':'disabled'}>② 练 · 五题闯关</button><button class="secondary-button" data-quiz-node="${n.id}" data-quiz-phase="pre" ${unlocked?'':'disabled'}>训练前测</button><button class="secondary-button" data-quiz-node="${n.id}" data-quiz-phase="post" ${passed?'':'disabled'}>③ 测 · 训练后测</button></div>${pre||post?`<p class="muted">前测：${pre?pre.correct+'/5':'未完成'}　后测：${post?post.correct+'/5':'未完成'}。同题复测存在记忆效应，差异仅供回顾。</p>`:''}</div></section>`;}).join('')}</div>`;}
 function quizHTML(){return `<section class="lab-card"><div class="card-top"><h2>${e(catalog.nodes.find(n=>n.id===quiz.node)?.title)} · ${{pre:'训练前测',post:'训练后测',practice:'五题练习'}[quiz.phase]}</h2>${button('返回地图','quiz-exit')}</div><form id="quiz-form">${quiz.questions.map((q,i)=>`<fieldset class="quiz-question"><legend>${i+1}. ${e(q.stem)}</legend>${q.options.map((opt,j)=>`<label><input type="${q.stem.includes('多选')?'checkbox':'radio'}" name="q${i}" value="${j}" ${quizResult?'disabled':''} ${quizResult?.results[i].selected.includes(j)?'checked':''}> <span>${String.fromCharCode(65+j)}. ${e(opt)}</span></label>`).join('')}<small>${e(q.reference.kind)} · ${e(q.reference.exercise)} · <a target="_blank" rel="noopener" href="${e(q.reference.url)}">教材 P${q.reference.printedPage} ↗</a></small>${quizResult?`<div class="answer-review ${quizResult.results[i].correct?'correct':'needs-work'}"><b>${quizResult.results[i].correct?'✓ 正确':'需要修正'} · 参考选项 ${quizResult.results[i].answer.map(a=>String.fromCharCode(65+a)).join('、')}</b><p>${e(quizResult.results[i].explanation)}</p>${(quizResult.results[i].diagnosis||[]).map(d=>'<p>'+String.fromCharCode(65+d.option)+'：'+e(d.reason)+'</p>').join('')}${!quizResult.results[i].correct?'<p>本题待巩固：'+e(q.stem)+'。请对照教材说明其他选项为何不适用。</p>':''}</div>`:''}</fieldset>`).join('')}${quizResult?`<div class="quiz-result"><strong>${quizResult.correct} / 5</strong><p>${quizResult.passed?'已达到四题通过标准。':'还差一点，请回到教材修正理解后再练。'}${quiz.phase!=='practice'?'本次为测评记录，不用于节点解锁。':''}</p>${button('返回学习地图','quiz-exit','primary-button')}${button('写一张复盘卡','reflect')}</div>`:'<button class="primary-button" type="submit">提交并查看逐题解析</button>'}<p id="quiz-error" role="status"></p></form></section>`;}
 function battleHTML(){if(battle)return currentBattleHTML();return `<div class="lab-grid battle-intro"><section class="lab-card"><span class="seal terracotta-seal">逻辑擂台</span><h2>与观点交锋，<br>为判断负责。</h2>${arenaVoice()}<p>对手会故意使用有缺口的论证。你的任务是指出缺口并给出理由。无需只猜术语，解释成立同样可以通过。</p><form id="battle-form"><label>议题<input name="topic" maxlength="1000" required value="人工智能与独立思考"></label><label>挑战时限<select name="seconds"><option value="30">30 秒 · 极限挑战</option><option value="60" selected>60 秒 · 标准强度</option><option value="120">120 秒 · 深度推敲</option></select></label><label>谬误难度<select name="level"><option value="1">初级 · 显著谬误，片段提示</option><option value="2">中级 · 隐蔽谬误</option><option value="3">高级 · 复合谬误</option></select></label><label><input name="sound" type="checkbox"> 开启倒计时提示音</label><button class="primary-button" type="submit">加载本轮题目 →</button><p id="battle-error" role="status"></p></form></section><section class="lab-card battle-guide"><h3>本场规则</h3><ol><li>题目加载完成后，点击开始才计时，模型等待不占作答时间。</li><li>选择谬误标签可记录识别时间；反驳还需要说明理由。</li><li>停笔后的完整反驳会触发教练质检，每轮最多三次；检查时暂停计时。发现明确的推理缺口后，教练提示并等待你继续。也可主动切换教练视角。</li><li>时间到会锁定输入。失败后可不计时补答，再看复盘。</li></ol><p class="muted">语音可用时支持连续交谈和打断朗读；文字输入始终可用。</p></section></div>${battleHistory()}`;}
 function currentBattleHTML(){if(battle.report)return reportHTML(battle.report);return `<section class="battle-arena lab-card"><div class="card-top"><h2>${battle.level===1?'初级':battle.level===2?'中级':'高级'} · ${e(battle.topic)}</h2><span>限时 ${battle.seconds} 秒</span></div>${arenaVoice()}<div class="battle-clock"><strong id="battle-remaining">${battle.seconds}</strong><span>秒</span><div class="clock-track"><div id="battle-progress"></div></div></div><div class="opponent"><span class="role-avatar">辩</span><div><b>诡辩士 · 练习论证</b><p>${battle.clue?e(battle.challenge).replace(e(battle.clue),'<mark>'+e(battle.clue)+'</mark>'):e(battle.challenge)}</p></div></div>${!battle.armed?`<p>题目已经就绪。准备好后再开始计时。</p>${button('开始本轮计时','battle-arm','primary-button')}`:`<div class="fallacy-tags" aria-label="谬误快捷标签">${battle.labels.map(f=>`<button data-fallacy-label="${f.id}" class="${battle.label===f.id?'selected':''}" ${battle.expired||battle.paused?'disabled':''}>${e(f.term)}</button>`).join('')}</div><form id="battle-answer-form"><label>你的反驳<textarea id="battle-answer" name="answer" maxlength="4000" rows="5" ${battle.expired||battle.paused?'disabled':''} placeholder="指出哪一步推理不足，并说明理由…">${e(battle.draft||'')}</textarea></label><div class="node-actions"><button type="submit" class="primary-button" ${battle.expired||battle.paused?'disabled':''}>提交反驳</button>${button('切换教练视角 · 暂停','battle-coach')}${button('结束并复盘','battle-end')}</div></form><div id="coach-hint" class="coach-hint" ${battle.paused?'':'hidden'}>${battle.coach?`<b>教练视角 · ${e(battle.coach.type)}</b>${battle.coach.quote?'<blockquote>'+e(battle.coach.quote)+'</blockquote>':''}<p>${e(battle.coach.reason)}</p>${button('返回对战，继续计时','battle-resume','primary-button')}`:''}</div>`}<p id="battle-error" role="status"></p></section>`;}
 function reportHTML(report){const retake=report.retake;return `<section class="lab-card"><span class="studio-kicker">高压逻辑对抗体检报告</span><h2>${report.correct?'本轮反驳通过':'本轮结束，继续检验理解'}</h2><p>${report.timedOut?'时间已到，限时作答结束。':''}${e(report.feedback.feedback)}</p><div class="studio-metrics"><div><strong>${report.identifyMs===null?'未标记':(report.identifyMs/1000).toFixed(1)+'s'}</strong><span>标签标记时间</span></div><div><strong>${(report.elapsedMs/1000).toFixed(1)}s</strong><span>提交 / 截止时间</span></div><div><strong>${report.label?report.labelCorrect?'正确':'待修正':'未选择'}</strong><span>标签识别</span></div><div><strong>${report.correct?'通过':'未通过'}</strong><span>反驳质量</span></div></div><details><summary>回看原题、我的反驳与解析</summary><blockquote>${e(report.challenge)}</blockquote><p>我的反驳：${e(report.answer||'未提交')}</p>${report.targets.map(f=>`<p><b>${e(f.term)}</b>：${e(f.definition)}</p>`).join('')}</details>${report.feedback.userFallacy?`<div class="coach-hint"><b>教练视角 · ${e(report.feedback.userFallacy.type)}</b><blockquote>${e(report.feedback.userFallacy.quote)}</blockquote><p>${e(report.feedback.userFallacy.reason)}</p></div>`:''}${confusionTable(report.feedback.confusions)}${!report.correct&&!retake?`<form id="retake-form"><h3>不计时补答</h3><p>先按自己的理解补充理由，再对照反馈。补答用于学习，不计竞技积分；已查看解析后的作答也可能受到提示影响。</p><textarea id="retake-answer" required maxlength="4000" rows="4" placeholder="重新组织你的反驳…"></textarea><button class="primary-button" type="submit">提交补答</button><p id="retake-error"></p></form>`:''}${retake?`<div class="answer-review"><h3>补答反馈</h3><p>${e(retake.feedback.feedback)}</p><p>${e(retake.interpretation)}</p></div>`:''}<div class="node-actions">${button('继续下一回合','battle-next','primary-button')}${button('写一张复盘卡','reflect')}${button('回到教材巩固','learning')}</div></section>${battleHistory()}`;}
 function confusionTable(items=[]){if(!items.length)return '<p class="muted">本轮没有记录到有明确原话依据的概念混淆。</p>';return `<h3>概念混淆复盘纪要</h3><div class="table-scroll"><table><thead><tr><th>混淆的概念与原话</th><th>冲突原因</th><th>教材定位</th><th>改进建议</th></tr></thead><tbody>${items.map(c=>`<tr><td>${e(c.concept)} / ${e(c.contrast)}<blockquote>${e(c.quote)}</blockquote></td><td>${e(c.reason)}</td><td>${c.references?.map(r=>`<a target="_blank" rel="noopener" href="${e(r.url)}">${e(r.chapter)} P${r.printedPage}</a><p>${e(r.text.slice(0,180))}…</p>`).join('')||'—'}</td><td>${e(c.suggestion)}</td></tr>`).join('')}</tbody></table></div>`;}
 function battleHistory(){if(!data.battles.length)return '';const values=data.battles.slice(-12),w=560,h=150;const valid=values.filter(r=>r.identifyMs!==null);const pts=values.map((r,i)=>r.identifyMs===null?null:[30+i*(w-60)/Math.max(1,values.length-1),h-20-r.identifyMs/1000/120*(h-40)]);const segments=pts.map((p,i)=>p&&pts[i-1]?`<line x1="${pts[i-1][0]}" y1="${pts[i-1][1]}" x2="${p[0]}" y2="${p[1]}" stroke="#2d7264" stroke-width="2"/>`:'').join('');return `<section class="lab-card"><div class="card-top"><h3>反应时间与准确率</h3><span>最近 ${values.length} 回合</span></div><p>反驳通过率 ${Math.round(values.filter(r=>r.correct).length/values.length*100)}% · 标签准确率 ${valid.length?Math.round(valid.filter(r=>r.labelCorrect).length/valid.length*100)+'%':'待观察'}（已标记 ${valid.length} 轮）</p><svg class="reaction-chart" viewBox="0 0 ${w} ${h+25}" role="img" aria-label="每回合标签标记时间，零到120秒"><text x="0" y="15">120s</text><text x="0" y="${h-20}">0s</text>${segments}${pts.map((p,i)=>p?`<circle cx="${p[0]}" cy="${p[1]}" r="5" fill="#2d7264"><title>第${i+1}轮 ${(values[i].identifyMs/1000).toFixed(1)}秒</title></circle><text x="${p[0]}" y="${h+5}" text-anchor="middle">${i+1}</text>`:'').join('')}</svg><p class="muted">记录的是标记时间，不直接等同于识破时间；未标记回合保持空缺。超时和补答结果分开展示。</p><div class="recent-battles">${values.slice().reverse().map(r=>`<button data-battle-report="${r.id}">${e(r.topic)} · ${r.correct?'通过':r.timedOut?'超时':'待完善'}${r.retake?' · 已补答':''} ↗</button>`).join('')}</div></section>`;}
 function argumentHTML(){return `<section class="lab-card"><h2>把原文放在证据旁边。</h2><p>可以只分析一篇自己的文章，也可以输入两篇文本，比较核心主张、论据类型与推理结构。</p><form id="argument-form"><div class="dual-input"><label>文本 A<textarea id="argument-a" required maxlength="16000" rows="8" placeholder="粘贴文章或论证…"></textarea></label><label>文本 B · 对比时填写<textarea id="argument-b" maxlength="16000" rows="8" placeholder="留空则进行单篇自测与批改…"></textarea></label></div><button class="primary-button" type="submit">分析论证 / 生成对比报告</button><p id="argument-error" role="status"></p></form></section><div id="argument-result">${data.essays.length?essayHTML(data.essays.at(-1)):''}</div>`;}
 function annotated(original,annotations){const pieces=[];let pos=0;const all=annotations.map(a=>({...a,start:original.indexOf(a.quote),end:original.indexOf(a.quote)+a.quote.length})).sort((a,b)=>a.start-b.start||b.end-a.end);for(const a of all){if(a.start<pos)continue;pieces.push(e(original.slice(pos,a.start)),`<mark class="annotation ${e(a.kind)}" title="${e(a.reason)}">${e(a.quote)}</mark>`);pos=a.end;}pieces.push(e(original.slice(pos)));return pieces.join('');}
 function argumentGraph(result){return argumentDiagram(result);}

 function essayHTML(r){const one=(original,result,label)=>`<section class="lab-card essay-column"><h3>${label} · ${e(result.claim)}</h3><div class="marked-original">${annotated(original,result.annotations)}</div><p>${e(result.summary)}</p><div>${radar(result.ratings)}</div><details><summary>五维评分与原话依据</summary>${result.ratings.map(d=>`<p><b>${e(d.label)}：${d.score===null?'待观察':d.score+'/4'}</b></p><blockquote>${e(d.quote)}</blockquote><p>${e(d.reason)}</p>`).join('')}</details><details><summary>逐处批改与修改建议</summary>${result.annotations.map(a=>`<blockquote>${e(a.quote)}</blockquote><p>${e(a.reason)}</p>`).join('')}</details><details open><summary>论证思维导图</summary>${argumentGraph(result)}</details></section>`;return `${r.comparison?`<section class="lab-card comparison-report"><h2>文本差异分析报告</h2>${[['claim','核心主张'],['evidence','论据类型与运用'],['structure','逻辑结构'],['suggestions','修改方向']].map(([k,t])=>`<h3>${t}</h3><p>${e(r.comparison[k])}</p>`).join('')}</section>`:''}<div class="${r.right?'essay-dual':'essay-single'}">${one(r.a,r.left,'文本 A')}${r.right?one(r.b,r.right,'文本 B'):''}</div>`;}
 function roundtableHTML(){const table=data.tables.at(-1);return `<section class="lab-card"><span class="seal">众议有据</span><h2>让不同视角坐到同一张桌前。</h2><p>角色为教学模拟。关注各自的理由、价值前提与证据，保留有依据的分歧。</p><form id="table-form"><label>讨论议题<input id="table-topic" maxlength="2000" required placeholder="例如：学校是否应允许学生用AI辅助写作？" value="${e(table?.topic||'')}"></label><button class="primary-button" type="submit">邀请角色，开始圆桌</button><p id="table-error" role="status"></p></form></section><div id="table-result">${table?tableHTML(table):''}</div>`;}
 function tableHTML(t){const names=[...new Set(t.history.map(s=>s.name))];return `<section class="lab-card roundtable"><div class="roundtable-seats">${names.map((name,i)=>`<button data-role-target="${e(name)}"><span class="role-avatar role-${i%5}">${e(name.slice(0,1))}</span>${e(name)}<small>@ 深入追问</small></button>`).join('')}</div><div class="table-messages">${t.history.map((s,i)=>`<article class="table-bubble"><span class="role-avatar role-${names.indexOf(s.name)%5}">${e(s.name.slice(0,1))}</span><div><b>${e(s.name)}</b><small>${e(s.value)}</small>${s.respondsTo?'<span class="reply-to">回应 '+e(s.respondsTo)+'</span>':''}<p>${e(s.statement)}</p><button data-role-target="${e(s.name)}">@ 继续追问</button><button data-role-battle="${e(s.name)}">挑战这个观点 ↗</button></div></article>`).join('')}</div><div class="table-synthesis"><h3>权衡与可能共识</h3><p>${e(t.tradeoff)}</p><p>${e(t.question)}</p></div><form id="table-followup"><label>选择一位角色<select id="table-target"><option value="">全桌 · 继续交锋</option>${names.map(n=>`<option>${e(n)}</option>`).join('')}</select></label><label>追问<input id="table-question" maxlength="3000" required placeholder="针对他的理由、前提或局限继续提问…"></label><button class="primary-button" type="submit">@ 角色，继续讨论</button><p id="followup-error" role="status"></p></form></section>`;}
 function profileHTML(){
  const session=panelSession,latest=latestConversationAssessment(data.assessments,session?.id),socratic=latestConversationAssessment(data.assessments,session?.id,'socratic');
  const trace=session?.messages.filter(m=>m.socraticTrace&&!m.error).at(-1);
  const strong=latest?.ratings.filter(d=>d.score!==null).sort((a,b)=>b.score-a.score)[0],weak=latest?.ratings.filter(d=>d.score!==null&&d.score<3).sort((a,b)=>a.score-b.score)[0];
  const records=conversationRecords(session);
  return `<section class="lab-card"><div class="card-top"><h2>当前对话 · 思考画像</h2>${button('根据当前对话更新画像','profile-refresh','primary-button')}</div><p>${strong?'本次对话中，“'+e(strong.label)+'”表现相对突出。':''}${weak?'下一步可巩固“'+e(weak.label)+'”。':latest?!strong?'当前材料尚不足以评价这些维度，请继续交流后再更新。':'尚未观察到的维度保持待观察。':records.length?'点击更新，根据本次实际发言生成反馈。':'当前对话还没有可评价的发言，请先与这位伙伴交流。'}</p><p class="muted">仅分析当前会话，不混入其他历史对话。${records.length===20?'本次取当前会话最近 20 条有效发言。':''}画像记录任务表现，材料不足的维度保持待观察。</p><p id="profile-error" role="status"></p></section>${latest?assessmentCard(latest,data.assessments.indexOf(latest)):'<section class="lab-card empty-state">本次对话尚未生成学习画像。</section>'}${trace||socratic?'<details class="lab-card"><summary>本次苏格拉底追问 · 思考轨迹与六维反馈</summary>'+(trace?traceMap(trace.socraticTrace.records,trace.trajectory):'')+(socratic?assessmentCard(socratic,data.assessments.indexOf(socratic)):'')+'</details>':''}<section class="lab-card"><div class="card-top"><h3>本次复盘卡</h3>${button('写一张复盘卡','reflect')}</div>${data.reflections.filter(r=>session?.id&&r.session===session.id).slice(-5).reverse().map(r=>`<details><summary>${when(r.time)} · ${e(r.gain.slice(0,30))}</summary><p>本次收获：${e(r.gain)}</p><p>逻辑盲区：${e(r.blind)}</p><p>高光时刻：${e(r.highlight)}</p><p>明日行动：${e(r.next)}</p></details>`).join('')||'<p>记录当前对话的收获和下一步。</p>'}</section>`;
 }
 const toolTitles={learning:'概念智析 · 教材定位与专项练习',compass:'知识罗盘 · 微目标闯关',duel:'诡辩士 · 连续对战',battle:'诡辩士 · 限时对战',argument:'论证分析 · 文章自测与双栏对比',roundtable:'多元洞察 · 思辨圆桌',profile:'思考轨迹与表现反馈'};
 async function render(next=tab){
  if(!toolTitles[next])return;
  tab=next;const sequence=++renderSequence;$('workspace-dialog-title').textContent=toolTitles[tab];
  if(!catalog){host.innerHTML='<p class="empty-state">正在准备专项工具…</p>';try{catalog=await ctx.api('/api/learning');}catch(err){host.innerHTML='<p>'+e(err.message)+'</p>';return;}}
  const html=tab==='compass'?await compass.html():({learning,duel:duelHTML,battle:battleHTML,argument:argumentHTML,roundtable:roundtableHTML,profile:profileHTML}[tab])();
  if(sequence!==renderSequence)return;host.innerHTML=html;
  if(tab==='battle'&&battle?.armed&&!battle.report)startClock();
 }
 async function task(form,id,work){if(loadBusy){ctx.toast('正在处理当前任务，请稍候。');return;}loadBusy=true;const buttons=[...form.querySelectorAll('button')],states=buttons.map(b=>b.disabled),trigger=document.activeElement?.closest('button'),label=trigger?.textContent;const showPending=trigger&&form.contains(trigger);if(showPending){trigger.textContent='正在处理…';trigger.setAttribute('aria-busy','true');}buttons.forEach(b=>b.disabled=true);const result=$(id);if(result)result.textContent='正在处理，请稍候…';try{await work();}catch(err){if($(id))$(id).textContent=err.message;else ctx.toast(err.message);}finally{loadBusy=false;buttons.forEach((b,i)=>b.disabled=states[i]);if(showPending){trigger.textContent=label;trigger.removeAttribute('aria-busy');}}}
 async function accountUpdate(u){compass.reset();account=u;scope=u?.id||'guest';read();quiz=null;quizResult=null;clearInterval(tick);battle=null;ctx.changeAccount(u);$('account-button').textContent=u?u.name+' · '+u.tier:'登录 / 注册';if(!host.hidden)render();}
 function reflect(){reflectionSessionId=workspace.open?panelSession?.id:ctx.session()?.id;showDialog('把这次思考带到下一次',`<form id="reflection-form"><label>本次收获<textarea name="gain" rows="2" required maxlength="2000"></textarea></label><label>逻辑盲区<textarea name="blind" rows="2" maxlength="2000"></textarea></label><label>高光时刻<textarea name="highlight" rows="2" maxlength="2000"></textarea></label><label>明日行动<input name="next" maxlength="1000"></label><div class="dialog-actions"><button type="submit" class="primary-button">保存复盘卡</button></div></form>`);}
 function startClock(){clearInterval(tick);tick=setInterval(()=>{if(!battle?.armed||battle.report||battle.paused)return;const left=Math.max(0,battle.deadline-(Date.now()+clockOffset)),value=Math.ceil(left/1000);if($('battle-remaining')){$('battle-remaining').textContent=value;$('battle-progress').style.width=left/(battle.seconds*1000)*100+'%';$('battle-progress').style.background=value<=10?'#b65d45':value<=battle.seconds/2?'#c59d4d':'#378577';}if(battle.sound&&value!==battle.lastSecond&&value>0&&value<=10)beep();battle.lastSecond=value;if(left<=0){battle.expired=true;battle.draft=$('battle-answer')?.value||battle.draft||'';clearInterval(tick);lockBattle();submitBattle(true);}},150);}
 function beep(){try{const AC=window.AudioContext||window.webkitAudioContext;if(!AC)return;const audio=beep.audio||(beep.audio=new AC()),o=audio.createOscillator(),g=audio.createGain();g.gain.value=.025;o.frequency.value=560;o.connect(g);g.connect(audio.destination);o.start();o.stop(audio.currentTime+.045);}catch{}}
 function lockBattle(){if($('battle-answer'))$('battle-answer').disabled=true;document.querySelectorAll('[data-fallacy-label],#battle-answer-form button').forEach(b=>b.disabled=true);}
 let draftTimer=null;
 host.addEventListener('input',ev=>{if(ev.target.id!=='battle-answer'||!battle?.armed||battle.paused||battle.expired||battle.report)return;battle.draft=ev.target.value;clearTimeout(draftTimer);if(battle.draft.trim().length<18||!/[。！？.!?]$/.test(battle.draft.trim()))return;draftTimer=setTimeout(()=>checkDraft(),3500);});
 async function checkDraft(){
  if(!battle?.armed||battle.report||battle.paused||battle.expired||battle.submitting||host.hidden||tab!=='battle'||(battle.autoChecks||0)>=3)return;
  const draft=$('battle-answer')?.value?.trim();if(!draft||draft===battle.lastChecked)return;const pausedAt=Date.now();
  battle.lastChecked=draft;battle.autoChecks=(battle.autoChecks||0)+1;battle.draft=draft;battle.paused=true;clearInterval(tick);lockBattle();if($('battle-error'))$('battle-error').textContent='教练正在检查这段推理，计时暂停…';
  try{const r=await ctx.api('/api/battle/coach',{id:battle.id,answer:draft});if(r.coach.type!=='检查推理'||host.hidden||tab!=='battle'){battle.coach=r.coach;render('battle');return;}const next=await ctx.api('/api/battle/resume',{id:battle.id});battle.paused=false;battle.deadline=next.deadline;clockOffset=next.serverNow-Date.now();render('battle');startClock();}
  catch(err){battle.deadline+=Date.now()-pausedAt;battle.paused=false;ctx.toast('草稿检查暂未完成：'+err.message);render('battle');startClock();}
 }
 async function submitBattle(expired=false){if(!battle||battle.report||battle.submitting)return;battle.draft=$('battle-answer')?.value||battle.draft||'';battle.submitting=true;lockBattle();clearInterval(tick);if($('battle-error'))$('battle-error').textContent='本轮已结束，正在评阅反驳…';try{const r=await ctx.api('/api/battle/submit',{id:battle.id,answer:battle.draft});battle.report=r;data.battles.push(r);if(r.user)account=r.user;save();render('battle');if(voiceEnabled)speak(r.feedback.feedback);}catch(err){if($('battle-error')){$('battle-error').textContent=err.message;const retry=document.createElement('button');retry.textContent='重试评阅';retry.className='secondary-button';retry.onclick=()=>submitBattle(expired);$('battle-error').append(retry);}}finally{battle.submitting=false;}}
 async function compareRating(select){const r=data.assessments[Number(select.dataset.assessmentCompare)],card=select.closest('.assessment-card');let c=null,note='仅显示当前对话的最新表现。';if(select.value==='baseline'){c=data.assessments.find(a=>a.baseline&&a.session===r.session&&a.kind===r.kind)?.ratings;note=c?'本次会话初始表达与当前表现对照；材料量可能不同，仅供回顾。':'本次会话尚无初始评价。';}card.querySelector('.radar-slot').innerHTML=radar(r.ratings,c);card.querySelector('.compare-note').textContent=note;}
 host.addEventListener('change',ev=>{if(ev.target.matches('[data-assessment-compare]'))compareRating(ev.target);});
 document.addEventListener('keydown',ev=>{if((ev.key==='Enter'||ev.key===' ')&&ev.target.matches('[data-axis-index],[data-graph-quote]')){ev.preventDefault();ev.target.dispatchEvent(new MouseEvent('click',{bubbles:true}));}});
 document.addEventListener('click',async ev=>{
  let t=ev.target.closest('button');const graphNode=ev.target.closest('[data-graph-quote]');if(graphNode){showDialog(graphNode.dataset.graphLabel,'<blockquote>'+e(graphNode.dataset.graphQuote)+'</blockquote>');return;}const axis=ev.target.closest('[data-axis-index]');if(axis&&axis.closest('[data-assessment]')){t={dataset:{rating:axis.closest('[data-assessment]').dataset.assessment+':'+axis.dataset.axisIndex},hasAttribute:()=>false};}if(!t)return;
  if(t.hasAttribute('data-auth-close'))auth.close();if(t.hasAttribute('data-studio-close'))dialog.close();
  if(t.hasAttribute('data-close-workspace')){closeWorkspace();return;}
  if(t.hasAttribute('data-expand-diagram')){const source=t.closest('.interactive-diagram');showDialog(source.querySelector('h4').textContent,'<div class="interactive-diagram expanded-diagram">'+source.innerHTML.replace(/<button[^>]*data-expand-diagram[^>]*>.*?<\/button>/,'')+'</div>');return;}
  if(t.dataset.zoom){const svg=t.closest('.interactive-diagram').querySelector('svg');const scale=t.dataset.zoom==='reset'?1:Math.max(.5,Math.min(3,Number(svg.dataset.scale||1)+(t.dataset.zoom==='+'?.25:-.25)));svg.dataset.scale=scale;svg.style.width=scale*100+'%';return;}
  if(t.dataset.chatAction){await ctx.send(t.dataset.chatAction);return;}
  if(t.dataset.studioTab){if(battle?.armed&&!battle.report&&!battle.paused&&t.dataset.studioTab!=='battle'){ctx.toast('请先结束当前对战或切换教练视角暂停计时。');return;}await mount(t.dataset.studioTab);}
  if(t.dataset.rating){const [i,j]=t.dataset.rating.split(':').map(Number),r=data.assessments[i],d=r.ratings[j];showDialog(d.label+' · 评分依据',`<p>${e(d.criterion)}</p>${d.quote?'<blockquote>'+e(d.quote)+'</blockquote>':''}<p>${e(d.reason)}</p>${d.record!==null?'<details><summary>展开对应的用户原话</summary><p>'+e(r.records[d.record])+'</p></details>':''}<p class="muted">${d.score===null?'本次材料不足，保持待观察。':'本次任务表现 '+d.score+' / 4；并非标准化能力分数。'}</p>`);}
  if(t.dataset.quizNode){try{quiz=await ctx.api('/api/quiz/start',{node:t.dataset.quizNode,phase:t.dataset.quizPhase,level:(data.quizReports.filter(r=>r.node===t.dataset.quizNode&&r.phase==='practice').at(-1)?.correct??0)>=4?2:1});quizResult=null;render('learning');}catch(err){ctx.toast(err.message);}}
  if(t.dataset.fallacyLabel&&!battle?.paused){try{const result=await ctx.api('/api/battle/identify',{id:battle.id,label:t.dataset.fallacyLabel});battle.label=result.label;battle.identifyMs=result.identifyMs;document.querySelectorAll('[data-fallacy-label]').forEach(b=>b.classList.toggle('selected',b.dataset.fallacyLabel===battle.label));}catch(err){ctx.toast(err.message);}}
  if(t.dataset.roleTarget){if($('table-target'))$('table-target').value=t.dataset.roleTarget;$('table-question')?.focus();}
  if(t.dataset.roleBattle){const table=data.tables.at(-1),speaker=table.history.filter(s=>s.name===t.dataset.roleBattle).at(-1);closeWorkspace();await ctx.startDebate('开始对战，中级。挑战'+speaker.name+'的观点：'+speaker.statement);}
  if(t.dataset.battleReport){const r=data.battles.find(r=>r.id===t.dataset.battleReport);battle={id:r.id,report:r};render('battle');}
  const action=t.dataset.studioAction;if(!action)return;
  if(action==='coach')ctx.coach();
  if(action==='account'){if(ctx.isBusy()||background||loadBusy){ctx.toast('请先等待当前训练反馈完成。');return;}if(account)showDialog('我的账号',`<h3>${e(account.name)} · ${e(account.tier)}</h3><p>逻辑值 ${account.points} · 练习 ${account.days} 天</p><p>账号、积分与徽章保存在本机后端。个人对话与答题明细保存在当前浏览器。</p>${button('退出登录','logout')}`);else auth.showModal();}
  if(action==='logout'){if(battle?.armed&&!battle.report){ctx.toast('请先结束当前对战再退出账号。');return;}await ctx.api('/api/auth/logout',{});dialog.close();await accountUpdate(null);}
  if(action==='reflect')reflect();
  if(action==='voice')await toggleVoice();
  if(action==='voice-stop'){window.speechSynthesis?.cancel();ctx.interrupt();}
  if(action==='quiz-exit'){quiz=null;quizResult=null;render('learning');}
  if(action==='learning')mount('learning');
  if(action==='battle-next'){battle=null;render('battle');}
  if(action==='battle-arm'){try{const r=await ctx.api('/api/battle/arm',{id:battle.id});clockOffset=r.serverNow-Date.now();battle.deadline=r.deadline;battle.armed=true;render('battle');startClock();}catch(err){ctx.toast(err.message);}}
  if(action==='battle-end')submitBattle();
  if(action==='battle-coach'){const pausedAt=Date.now();const draft=$('battle-answer')?.value||'';if(!draft.trim()){ctx.toast('先写下你的反驳，教练才能检查其中的推理。');return;}battle.draft=draft;battle.paused=true;clearInterval(tick);lockBattle();try{const r=await ctx.api('/api/battle/coach',{id:battle.id,answer:draft});battle.coach=r.coach;render('battle');}catch(err){battle.deadline+=Date.now()-pausedAt;battle.paused=false;ctx.toast(err.message);render('battle');startClock();}}
  if(action==='battle-resume'){try{const r=await ctx.api('/api/battle/resume',{id:battle.id});battle.deadline=r.deadline;clockOffset=r.serverNow-Date.now();battle.paused=false;render('battle');startClock();}catch(err){ctx.toast(err.message);}}
  if(action==='profile-refresh'){const session=panelSession,records=conversationRecords(session);if(!session||!records.length){$('profile-error').textContent='当前对话还没有可评价的发言，请先与这位伙伴交流。';return;}await task(host,'profile-error',async()=>{const r=await ctx.api('/api/lab/evaluate',{kind:'profile',records});addAssessment({...r,id:crypto.randomUUID(),session:session.id,agent:panelAgent});save();await render('profile');});}
 });
 auth.querySelector('form').onsubmit=async ev=>{ev.preventDefault();const form=ev.currentTarget;await task(form,'auth-result',async()=>{const r=await ctx.api('/api/auth/'+ev.submitter.value,{name:$('auth-name').value,password:$('auth-password').value});$('auth-password').value='';auth.close();await accountUpdate(r.user);});};
 document.addEventListener('submit',async ev=>{
  const form=ev.target;if(!['quiz-form','battle-form','battle-answer-form','retake-form','argument-form','table-form','table-followup','reflection-form','duel-form'].includes(form.id))return;ev.preventDefault();
  if(form.id==='duel-form'){const f=new FormData(form);closeWorkspace();await ctx.send('开始对战，'+f.get('level')+'，场景：'+f.get('scene')+'。议题：'+f.get('topic'));return;}
  if(form.id==='quiz-form'){const answers=quiz.questions.map((_,i)=>[...form.querySelectorAll(`[name="q${i}"]:checked`)].map(x=>Number(x.value)));if(answers.some(a=>!a.length)){$('quiz-error').textContent='请先完成所有五道题。';return;}await task(form,'quiz-error',async()=>{quizResult=await ctx.api('/api/quiz/submit',{id:quiz.id,answers});data.quizReports.push(quizResult);if(quizResult.passed&&quiz.phase==='practice'&&!data.mastered.includes(quiz.node))data.mastered.push(quiz.node);if(quizResult.user)account=quizResult.user;save();render('learning');});}
  if(form.id==='battle-form')await task(form,'battle-error',async()=>{const fields=new FormData(form),sound=fields.has('sound');if(sound){beep();}battle=await ctx.api('/api/battle/start',{topic:fields.get('topic'),seconds:Number(fields.get('seconds')),level:Number(fields.get('level'))});battle.sound=sound;render('battle');if(voiceEnabled)speak(battle.challenge);});
  if(form.id==='battle-answer-form')submitBattle();
  if(form.id==='retake-form')await task(form,'retake-error',async()=>{const r=await ctx.api('/api/battle/retake',{id:battle.id,answer:$('retake-answer').value});battle.report.retake=r;const prior=data.battles.find(v=>v.id===battle.id);if(prior)prior.retake=r;save();render('battle');});
  if(form.id==='argument-form')await task(form,'argument-error',async()=>{const r=await ctx.api('/api/lab/argument',{a:$('argument-a').value,b:$('argument-b').value});data.essays.push(r);save();$('argument-result').innerHTML=essayHTML(r);});
  if(form.id==='table-form')await task(form,'table-error',async()=>{const r=await ctx.api('/api/lab/roundtable',{topic:$('table-topic').value});data.tables.push({...r,history:[...r.speakers]});save();$('table-result').innerHTML=tableHTML(data.tables.at(-1));});
  if(form.id==='table-followup')await task(form,'followup-error',async()=>{const table=data.tables.at(-1),r=await ctx.api('/api/lab/roundtable',{topic:table.topic,target:$('table-target').value,question:$('table-question').value,history:table.history});table.history.push(...r.speakers);table.tradeoff=r.tradeoff;table.question=r.question;const session=ctx.session();if(session?.training?.stages?.perspectives)session.training.stages.perspectives.tableHistory=table.history;const m=session?.messages.find(m=>m.table?.time===table.time);if(m){m.table={...table};ctx.refreshMessage(m);}ctx.persist();save();$('table-result').innerHTML=tableHTML(table);});
  if(form.id==='reflection-form'){const r=Object.fromEntries(new FormData(form));data.reflections.push({...r,session:reflectionSessionId,time:Date.now()});save();dialog.close();ctx.toast('复盘卡已保存到当前浏览器。');if(tab==='profile')render();}
 });
 function traceMap(records,trajectory){return thoughtDiagram(records,trajectory);}

 function renderArtifacts(message,node){const container=node.querySelector('.message-artifacts');if(!container)return;
  if(message.routed==='concept')conceptPictures.render(message,container);
  if(message.debate&&!container.querySelector('.debate-controls')){const d=message.debate,div=document.createElement('section');div.className='debate-controls';const current=ctx.session()?.messages.filter(m=>m.debate&&!m.error).at(-1)===message;if(current)document.querySelectorAll('.debate-controls').forEach(old=>{if(old.parentElement!==container)old.querySelectorAll('button').forEach(b=>b.remove());});div.innerHTML=d.status==='ended'?confusionTable(d.report.confusions)+'<p>整场记录已保存在本次对话。</p>':current?'<p>'+ (d.status==='paused'?'教练已暂停对手。你可以直接输入修正后的反驳，或继续交锋。':'持续围绕同一议题交锋，由你决定何时结束。')+'</p>'+(d.status==='paused'?'<button type="button" data-chat-action="继续对战">返回对战</button>':'')+'<button type="button" data-chat-action="结束对战">结束整场并复盘</button>':'';container.append(div);}
  if(message.socraticTrace?.records?.length&&!container.querySelector('.thought-map')){const div=document.createElement('details');div.className='lab-inline';div.innerHTML='<summary>展开我的思考轨迹 · 点击节点回看原话</summary>'+traceMap(message.socraticTrace.records,message.trajectory);container.append(div);}
  if(message.assessmentIds?.length&&!container.querySelector('.assessment-entry')){const b=document.createElement('button');b.className='inline-graph assessment-entry';b.textContent='◈ 查看本次评分、原话依据与历史对比 ↗';b.onclick=()=>mount('profile');container.append(b);}
  if(message.evaluationError&&!container.querySelector('.evaluation-retry')){const b=document.createElement('button');b.className='evaluation-retry secondary-button';b.textContent='重新生成表现反馈';b.onclick=()=>{delete message.evaluationError;afterTurn(message,ctx.session());};container.append(b);}
  if(message.conceptCard&&!container.querySelector('.concept-visual')){const c=message.conceptCard,div=document.createElement('div');div.className='concept-visual';div.innerHTML=`<h3>${e(c.term)} · 理解与边界</h3><div class="concept-three"><section><b>概念定义</b><p>${e(c.definition)}</p>${c.definitionSource?'<a target="_blank" rel="noopener" href="/api/textbook.pdf#page='+c.definitionSource.pdfPages[0]+'">教材 P'+c.definitionSource.printedPages[0]+' ↗</a>':''}${c.plain?'<p>'+e(c.plain)+'</p>':''}</section><section><b>正反案例 · 假设情境</b><p>${e(c.positive||c.example)}</p>${c.negative?'<p>'+e(c.negative)+'</p>':''}</section><section><b>易错辨析</b>${(c.misconceptions||[c.boundary]).map(x=>'<p>'+e(x)+'</p>').join('')}</section></div>`;container.append(div);}
  if(message.essay&&!container.querySelector('.essay-entry')){const div=document.createElement('div');div.className='essay-entry';div.innerHTML=essayHTML(message.essay);container.append(div);}
  if(message.routed==='planner'&&!container.querySelector('.learning-entry')){const b=document.createElement('button');b.className='inline-graph learning-entry';b.textContent='▤ 进入教材微目标 · 学、练、测 ↗';b.onclick=()=>mount('compass');container.append(b);}
  if(message.table&&!container.querySelector('.table-inline')){const div=document.createElement('div');div.className='table-inline';div.innerHTML=message.table.speakers.map((s,i)=>`<div class="table-bubble"><span class="role-avatar role-${i%5}">${e(s.name[0])}</span><div><b>${e(s.name)}</b><small>${e(s.value)}</small><p>${e(s.statement)}</p></div></div>`).join('');const b=document.createElement('button');b.className='secondary-button';b.textContent='进入圆桌 @角色继续追问';b.onclick=()=>{mount('roundtable');};div.append(b);container.append(div);}
 }
 async function afterTurn(message,session){
  if(!message.error&&session)void conceptPictures.enrich(message,session);
  if(message.error||!session||message.enriching)return;
  message.enriching=true;delete message.evaluationError;background++;
  try{
   if(!catalog)catalog=await ctx.api('/api/learning');
   if(message.socraticTrace?.complete&&!message.assessmentIds?.length&&!message.assessing){message.assessing=true;ctx.toast('五轮已完成，正在根据实际发言生成思考表现反馈。');const records=message.socraticTrace.records.map(r=>r.content),results=await Promise.all([ctx.api('/api/lab/evaluate',{kind:'socratic',records}),ctx.api('/api/lab/evaluate',{kind:'socratic',records:records.slice(0,1)}),ctx.api('/api/lab/evaluate',{kind:'profile',records})]);message.assessmentIds=[];results.forEach((r,i)=>{const id=crypto.randomUUID();addAssessment({...r,id,session:session.id,baseline:i===1});message.assessmentIds.push(id);});delete message.assessing;save();ctx.persist();ctx.refreshMessage(message);ctx.toast('思考轨迹和表现反馈已生成，可展开查看原话依据。');if(!dialog.open)reflect();}
   if(message.socraticTrace?.complete&&!message.trajectory){message.trajectory=await ctx.api('/api/lab/trajectory',{records:message.socraticTrace.records.map(r=>r.content)});ctx.persist();ctx.refreshMessage(message);}
   if(message.routed==='concept'&&!message.conceptCard&&session.training?.stages?.concept?.turns===1){const input=session.training.stages.concept.topic||'';const entry=catalog.concepts?.find(c=>[c.term,...c.aliases].some(k=>input.includes(k)));if(entry){message.conceptCard=await ctx.api('/api/lab/concept',{term:entry.term});ctx.persist();ctx.refreshMessage(message);}}
   if(message.routed==='argument'&&message.graph&&!message.essay){const original=session.training?.stages?.argument?.material;if(original){message.essay=await ctx.api('/api/lab/argument',{a:original});data.essays.push(message.essay);save();ctx.persist();ctx.refreshMessage(message);}}
   if(message.table&&!message.tableSaved){data.tables.push({...message.table,history:message.table.history||message.table.speakers});message.tableSaved=true;save();ctx.persist();ctx.refreshMessage(message);}
  if(message.routed!=='socratic'&&!(message.routed==='concept'&&session.training?.mode!=='systematic')&&session.training?.stages?.[message.routed]?.status==='complete'&&!message.profileId){const records=session.messages.filter(m=>m.role==='user'&&!m.error&&!/^(进入下一环节|暂时跳过|继续之前)/.test(m.content)).map(m=>m.content).slice(-20);const r=await ctx.api('/api/lab/evaluate',{kind:'profile',records});message.profileId=addAssessment({...r,id:crypto.randomUUID(),session:session.id}).id;save();ctx.persist();}
  }catch(err){message.evaluationError=err.message;delete message.assessing;ctx.persist();ctx.refreshMessage(message);ctx.toast('对话已保留，附加训练反馈暂未完成：'+err.message);}
  finally{delete message.enriching;background--;ctx.persist();ctx.refreshMessage(message);if(workspace.open&&panelSession?.id===session.id&&tab==='profile')await render('profile');}
 }
 function voiceStatus(text){$('voice-status').textContent=text;if($('battle-voice-status'))$('battle-voice-status').textContent=text;}
 function arenaVoice(){return `<div class="arena-voice">${button(voiceEnabled?'结束语音':'开启语音对战','voice')}${button('打断朗读','voice-stop')}<span id="battle-voice-status">${voiceEnabled?'正在聆听；开始计时后可语音反驳。':'浏览器语音识别与朗读；也可使用文字反驳。'}</span></div>`;}
 function speak(text){if(!voiceEnabled||!window.speechSynthesis)return;speechSynthesis.cancel();const utterance=new SpeechSynthesisUtterance(text.replace(/[#*`]/g,'').slice(0,6000));utterance.lang='zh-CN';utterance.rate=1;utterance.onstart=()=>{voiceStatus('正在朗读 · 可说话或点击打断');};utterance.onend=()=>{if(voiceEnabled)voiceStatus('正在聆听…');};speechSynthesis.speak(utterance);}
 async function toggleVoice(){if(voiceEnabled){voiceEnabled=false;voice?.abort();window.speechSynthesis?.cancel();voiceStatus('');$('voice-toggle').textContent='语音对话';return;}const SR=window.SpeechRecognition||window.webkitSpeechRecognition;if(!SR){ctx.toast('当前浏览器未提供语音识别。请在支持此功能的 Chrome 或 Edge 中打开本机地址。');return;}voice=new SR();voice.lang='zh-CN';voice.continuous=true;voice.interimResults=true;voiceEnabled=true;$('voice-toggle').textContent='结束语音';voiceStatus('等待麦克风授权…');voice.onspeechstart=()=>{window.speechSynthesis?.cancel();ctx.interrupt();voiceStatus('正在听你说…');};voice.onresult=async ev=>{let interim='',final='';for(let i=ev.resultIndex;i<ev.results.length;i++)if(ev.results[i].isFinal)final+=ev.results[i][0].transcript;else interim+=ev.results[i][0].transcript;voiceStatus(interim||'正在聆听…');if(final.trim()&&!voiceSending){voiceSending=true;try{if(tab==='battle'&&!host.hidden){if(battle?.armed&&!battle.report&&!battle.paused&&!battle.expired){$('battle-answer').value=final;await submitBattle();}else voiceStatus('请先加载题目并开始计时，再用语音反驳。');}else{await ctx.waitIdle();await ctx.sendVoice(final);}}finally{voiceSending=false;}}};voice.onerror=ev=>{if(['not-allowed','service-not-allowed','audio-capture','network'].includes(ev.error)){voiceEnabled=false;$('voice-toggle').textContent='语音对话';voiceStatus(({network:'语音识别服务无法连接，可继续文字对话。','audio-capture':'未找到可用麦克风。','not-allowed':'麦克风未获授权。','service-not-allowed':'浏览器语音服务不可用。'}[ev.error]));}};voice.onend=()=>{if(voiceEnabled)setTimeout(()=>{try{voice.start();}catch{}},300);};try{voice.start();}catch(err){voiceEnabled=false;ctx.toast(err.message);}}
 const accountButton=document.createElement('button');accountButton.id='account-button';accountButton.className='account-chip';accountButton.textContent='登录 / 注册';accountButton.dataset.studioAction='account';document.querySelector('.top-actions').prepend(accountButton);
 const tools=document.createElement('div');tools.className='workspace-tools';tools.id='workspace-tools';document.querySelector('.training-toolbar').after(tools);
 const voiceTools=document.createElement('div');voiceTools.className='voice-tools';voiceTools.innerHTML='<button id="voice-toggle" class="tool-button">语音对话</button><button id="voice-interrupt" class="tool-button">打断朗读</button><span id="voice-status" role="status"></span>';document.querySelector('.composer-bottom').before(voiceTools);$('voice-toggle').onclick=toggleVoice;$('voice-interrupt').onclick=()=>{window.speechSynthesis?.cancel();ctx.interrupt();};
 const companion=document.createElement('div');companion.className='thinking-companion';companion.innerHTML='<div class="scholar"><i class="scholar-head"></i><i class="scholar-body"></i><i class="scholar-hand"></i><i class="scholar-book"></i></div><span>我在听，慢慢想。</span>';document.querySelector('.conversation-top').append(companion);companion.classList.add('companion-compact');
 function duelHTML(){return `<section class="lab-card"><h2>诡辩士 · 连续交锋</h2><p>围绕同一议题相互回应。教练发现推理缺口时暂停提示，由你主动结束后统一复盘。</p><form id="duel-form"><label>议题<input name="topic" required maxlength="1800" placeholder="例如：学校是否应该允许学生用 AI 完成作业？"></label><div class="dual-input"><label>难度<select name="level"><option>初级</option><option>中级</option><option>高级</option></select></label><label>场景<select name="scene"><option>自由议题</option><option>职场沟通</option><option>家庭讨论</option></select></label></div><button type="submit" class="primary-button">开始连续对战</button></form><p>可以使用下方语音对话进行交锋。</p><button type="button" data-studio-tab="battle">另选单题限时练习</button></section>`;}
 async function mount(next){
  if(!toolTitles[next])return;
  const session=ctx.session(),agent=ctx.agent(),key=agent+':'+(session?.id||'new')+':'+next;
  if(tab!==next&&(loadBusy||compass.busy())){ctx.toast('请等待当前工具任务完成后再切换。');return;}
  panelSession=session||null;panelAgent=agent;
  if(!workspace.open)chatScroll=$('message-scroll').scrollTop;
  host.hidden=false;if(!workspace.open)workspace.showModal();
  if(loadedKey!==key||next==='profile'&&!loadBusy){await render(next);loadedKey=key;}else $('workspace-dialog-title').textContent=toolTitles[next];
 }
 function detach(){closeWorkspace();}
 function toolsFor(agent){
  const items=agent==='coach'?[['learning','教材闯关'],['duel','连续对战'],['argument','论证对比'],['roundtable','思辨圆桌']]:agent==='socratic'?[['profile','思考轨迹与表现反馈']]:agent==='fallacy'?[['duel','连续对战 · 选择难度']]:agent==='argument'?[['argument','文章自测 / 双栏对比']]:agent==='perspectives'?[['roundtable','邀请角色 · 圆桌讨论']]:agent==='planner'?[['compass','微目标闯关'],['profile','五维思维画像']]:[['learning','教材定位与专项练习']];
  tools.innerHTML=items.map(([id,label])=>`<button data-studio-tab="${id}">${label} ↗</button>`).join('');companion.hidden=!['coach','socratic'].includes(agent);
  const key=agent+':'+(ctx.session()?.id||'new');if(key!==workspaceKey){workspaceKey=key;closeWorkspace();loadedKey='';}
 }
 async function init(){try{const r=await ctx.api('/api/auth/me');await accountUpdate(r.user);}catch{}try{catalog=await ctx.api('/api/learning');}catch{}}
 return {init,render,mount,detach,toolsFor,renderArtifacts,afterTurn,speak,setThinking(value){companion.classList.toggle('is-thinking',value);companion.querySelector('span').textContent=value?'略作思索，接住你的想法。':'我在听，慢慢想。';},exportData:()=>data,clear(){data=getDefault();save();},busy:()=>loadBusy||compass.busy()||background>0||battle?.armed&&!battle.report&&!battle.paused};
}
